}

variables = sorted({v for vals in cycles.values() for v in vals})
freq = {v: sum(1 for vals in cycles.values() if v in vals) for v in variables}

# Weighted importance: frequency * 2 + presence in AI cycle * 3 + presence in crash/regulation/niche/memory/language
strategic = {"crash_confianza", "regulacion", "nichos_no_atendidos", "memoria_institucional_debil", "memoria_contextual_debil", "lenguaje_herramientas_limitado"}
score = {}
for v in variables:
    score[v] = freq[v]*2 + (3 if v in cycles["IA generativa 2022-2026"] else 0) + (2 if v in strategic else 0)

ranked = sorted(score.items(), key=lambda x: (-x[1], -freq[x[0]], x[0]))
for v, s in ranked:
    print(f"{s:2d} | freq={freq[v]} | {v}")
"}

